-- History pivot / #184: Renascimento e Grandes Navegações
-- Generated by generators/emit_trail_sql.py from generators/trail_renascimento_navegacoes.py.
-- Idempotent. One transaction. Pair with matching .rollback.sql.
-- DO NOT apply without owner go-ahead. Dry-run with BEGIN + RAISE EXCEPTION.

BEGIN;

INSERT INTO public.modulos (ordem, titulo, emoji, cor, categoria_id, descricao)
SELECT 22, 'Renascimento e Grandes Navegações', '🧭', '#0D9488', 1, 'Do humanismo italiano e da Reforma à ciência, ao Estado moderno e às travessias oceânicas: como a Europa se transformou e conectou os continentes — com comércio, violência, escravidão e resistência.'
WHERE NOT EXISTS (SELECT 1 FROM public.modulos WHERE titulo = 'Renascimento e Grandes Navegações');

CREATE TEMP TABLE _seed_trail AS
SELECT id AS modulo_id FROM public.modulos WHERE titulo = 'Renascimento e Grandes Navegações';

INSERT INTO public.niveis (modulo_id, ordem, titulo)
SELECT t.modulo_id, v.ordem, v.titulo
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 'Nível 1 - Cultura e religião'),
  (2, 'Nível 2 - Ciência e Estado'),
  (3, 'Nível 3 - Expansão marítima'),
  (4, 'Nível 4 - Mundo atlântico')
) AS v(ordem, titulo)
WHERE NOT EXISTS (
  SELECT 1 FROM public.niveis n WHERE n.modulo_id = t.modulo_id AND n.ordem = v.ordem
);

INSERT INTO public.submodulos (modulo_id, nivel_id, ordem, titulo, data_liberacao_desde_inicio, imagem_url)
SELECT t.modulo_id, n.id, v.ordem, v.titulo, 0, NULL
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 1, 'Humanismo e as cidades italianas'),
  (1, 2, 'Mecenato e tipografia'),
  (1, 3, 'Reforma e Contrarreforma'),
  (2, 4, 'Ciência e visão de mundo'),
  (2, 5, 'Estado moderno europeu'),
  (2, 6, 'Economia e capitalismo mercante'),
  (3, 7, 'Portugal e a rota africana'),
  (3, 8, 'Castela, Colombo e a América'),
  (3, 9, 'Impérios ultramarinos'),
  (4, 10, 'Encontro de povos e catástrofe demográfica'),
  (4, 11, 'Tráfico atlântico'),
  (4, 12, 'Mundo conectado em 1600')
) AS v(nivel_ordem, ordem, titulo)
JOIN public.niveis n ON n.modulo_id = t.modulo_id AND n.ordem = v.nivel_ordem
WHERE NOT EXISTS (
  SELECT 1 FROM public.submodulos s WHERE s.modulo_id = t.modulo_id AND s.ordem = v.ordem
);

INSERT INTO public.licoes (submodulo_id, ordem, titulo, emoji, conteudo)
SELECT s.id, 1, s.titulo, '🧭',
       jsonb_build_object('preview', v.preview)
FROM _seed_trail t
JOIN public.submodulos s ON s.modulo_id = t.modulo_id
JOIN (VALUES
  (1, 'Entre os séculos XIV e XVI, cidades-Estado como Florença, Veneza e Milão enriqueceram com comércio e finanças, e elites urbanas passaram a valorizar a leitura de autores latinos e gregos. Petrarca e os humanistas defenderam os studia humanitatis — gramática, retórica, poesia, história e filosofia moral — e o método de voltar às fontes. ''Renascimento'' é um rótulo posterior, consolidado no século XIX: a Idade Média não foi um simples apagão, e a maioria dos humanistas era cristã.'),
  (2, 'Banqueiros, príncipes e papas patrocinavam letrados, arquitetos e artistas por prestígio, legitimidade política e redes de influência — os Médici em Florença são o exemplo clássico. Por volta de 1450, Gutenberg combinou tipos móveis metálicos, tinta oleosa e prensa em Mainz; a técnica de tipos móveis já existia na Ásia, mas a impressão europeia baratou livros e acelerou a circulação de textos. Em 1500 havia prensas em centenas de cidades, e a censura e os índices de livros proibidos surgiram como resposta.'),
  (3, 'Em 1517, Martinho Lutero criticou a venda de indulgências; a imprensa, o apoio de príncipes alemães e tensões políticas transformaram a disputa em ruptura. Calvino organizou uma igreja reformada em Genebra, e Henrique VIII separou a Inglaterra de Roma em 1534 por motivos religiosos e dinásticos. A resposta católica incluiu o Concílio de Trento (1545–1563), a Companhia de Jesus e a Inquisição. A Paz de Augsburgo (1555) deixou o príncipe escolher a religião do território — liberdade de consciência individual ainda estava longe.'),
  (4, 'Em 1543, Copérnico publicou um modelo com o Sol próximo ao centro e Vesalius reorganizou a anatomia a partir da dissecação. Kepler descreveu órbitas elípticas; Galileu usou o telescópio, aperfeiçoado a partir de invenção holandesa, e foi julgado pela Inquisição em 1633. A ''Revolução Científica'' foi um processo longo, feito de instrumentos, correspondência entre estudiosos, cortes e universidades — e não de gênios isolados contra uma Igreja uniformemente inimiga da ciência.'),
  (5, 'Do século XV ao XVI, monarquias como França, Espanha, Inglaterra e Portugal ampliaram a capacidade de cobrar impostos, manter exércitos com pólvora e criar burocracias. Esse ''Estado moderno'' ainda não era nacional no sentido do século XIX, e reis negociavam com nobres, cidades, cortes e Igreja. A Itália dividida virou campo de disputa nas Guerras Italianas (1494–1559); Maquiavel, ex-secretário florentino, escreveu O Príncipe sobre poder e política sem nunca ter dito, literalmente, que ''os fins justificam os meios''.'),
  (6, 'Redes de comércio, bancos e crédito cresceram nas cidades italianas e depois em Antuérpia e Amsterdã. A letra de câmbio, a contabilidade por partidas dobradas e famílias como Médici e Fugger — que financiou a eleição imperial de Carlos V em 1519 — mostram um capitalismo mercante anterior à indústria. Estados praticaram políticas hoje chamadas de mercantilistas; a Companhia Holandesa das Índias Orientais (1602) combinou capital por ações e monopólio. A prata americana alimentou o comércio global e contribuiu para a alta de preços na Europa.'),
  (7, 'A conquista de Ceuta (1415) é marco usual da expansão portuguesa, motivada por cruzada, ouro, comércio e disputa de rotas. Navegadores avançaram pela costa africana com caravelas, bússola, astrolábio e saber de ventos e correntes herdado de várias culturas; feitorias como Elmina (1482) ligaram ouro e escravizados à Coroa. Bartolomeu Dias dobrou o extremo sul da África em 1488 e Vasco da Gama chegou a Calicute em 1498. A ''Escola de Sagres'' como academia náutica de Henrique é lenda historiográfica — ele patrocinou expedições, não há prova de escola formal.'),
  (8, 'Em 1492, Castela e Aragão, unidas pelo casamento de Isabel e Fernando, concluíram a conquista de Granada e aprovaram a viagem de Colombo ao oeste. Ele chegou ao Caribe acreditando estar perto da Ásia; a ideia de que ele ''provou que a Terra era redonda'' é mito — o debate era sobre o tamanho do planeta. O Tratado de Tordesilhas (1494) dividiu zonas de expansão entre Castela e Portugal sem consultar ninguém que já vivia nessas terras. Cortés (1519–1521) e Pizarro (1532–1533) conquistaram impérios com alianças indígenas, epidemias e violência.'),
  (9, 'Portugal montou uma rede de fortalezas e feitorias no Índico (Goa, 1510; Malaca, 1511) e, com Cabral (1500), alcançou a costa do atual Brasil. A Espanha organizou vice-reinos, extraiu prata de Potosí e Zacatecas e controlou o comércio pela Casa de Contratación. O Oceano Índico não era ''vazio'': já tinha circuitos ricos de comerciantes árabes, indianos, persas, suaílis e chineses. Entre 1580 e 1640, a União Ibérica juntou as coroas; depois, holandeses, ingleses e franceses disputaram rotas e territórios.'),
  (10, 'As Américas abrigavam sociedades diversas — mexicas, incas, maias, tupis e muitas outras. A chegada de europeus e africanos trouxe varíola, sarampo e outras doenças novas, somadas a guerra, trabalho forçado, deslocamentos e fome; as estimativas variam, mas indicam perdas de dezenas de milhões de pessoas. A encomienda e as Leyes Nuevas (1542) mostram disputas jurídicas dentro do império espanhol; frei Bartolomé de las Casas denunciou abusos, e povos indígenas resistiram, negociaram e se aliaram — não foram figurantes passivos.'),
  (11, 'Os portugueses começaram a levar africanos escravizados para a Europa nos anos 1440; no século XVI, plantations de açúcar nas ilhas atlânticas e no Brasil ampliaram a demanda. Estima-se que cerca de 12,5 milhões de pessoas foram embarcadas até meados do século XIX, e o Brasil foi o maior destino individual. Havia escravidão na África antes dos europeus, mas o tráfico atlântico foi um sistema comercial de escala inédita, com participação de elites africanas em relações desiguais, resistência armada, quilombos e ideologias racializadas que sustentaram o sistema.'),
  (12, 'Por volta de 1600, rotas ligavam Américas, Europa, África e Ásia: a troca colombiana espalhou milho, batata, cavalos, gado e doenças; o Galeão de Manila levava prata americana à China em troca de seda e porcelana. Em 1600–1602, surgiram companhias inglesa e holandesa das Índias Orientais. A Europa ainda não ''dominava o mundo'': a Ásia concentrava grande parte da produção e do comércio, com Ming, Mughal, Otomano e Tokugawa poderosos. A conexão foi real e desigual, com ganhos e perdas muito diferentes entre regiões.')
) AS v(sub_ordem, preview) ON v.sub_ordem = s.ordem
WHERE NOT EXISTS (SELECT 1 FROM public.licoes l WHERE l.submodulo_id = s.id);

